mapper.select:
select u.user_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.balance, u.frozen_balance, u.used_balance, u.request_count, u.billing_multiplier, u.billing_preference, u.ai_concurrency_limit, s.subscription_id as active_subscription_id, s.plan_title as active_subscription_title, s.amount_total as active_subscription_amount_total, s.amount_used as active_subscription_amount_used, s.end_time as active_subscription_end_time, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, d.dept_name, d.leader from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join ai_user_subscription s on s.subscription_id = ( select s2.subscription_id from ai_user_subscription s2 where s2.user_id = u.user_id and s2.status = 'active' and s2.end_time > sysdate() order by s2.end_time desc, s2.subscription_id desc limit 1 ) where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))
${params.dataScope}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update sys_user
dept_id = #{deptId}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, billing_multiplier = #{billingMultiplier}, billing_preference = #{billingPreference}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where user_id = #{userId}

update sys_user
set frozen_balance = frozen_balance + #{amount},
	update_time = sysdate()
where user_id = #{userId}
  and #{amount} >= 0
  and balance - frozen_balance >= #{amount}

update sys_user
set frozen_balance = frozen_balance - #{amount},
	update_time = sysdate()
where user_id = #{userId}
  and #{amount} >= 0
  and frozen_balance >= #{amount}

update sys_user
set balance = balance - #{walletCharged},
	frozen_balance = frozen_balance - #{walletReserved},
	used_balance = used_balance + #{actualCost},
	request_count = request_count + #{requestIncrement},
	update_time = sysdate()
where user_id = #{userId}
  and frozen_balance >= #{walletReserved}
  and balance - frozen_balance + #{walletReserved} >= #{walletCharged}

update sys_user
set balance = balance - #{amount},
	update_time = sysdate()
where user_id = #{userId}
  and balance - frozen_balance >= #{amount}
